begin;
select set_config('gatherly.creator',gen_random_uuid()::text,true),set_config('gatherly.buyer',gen_random_uuid()::text,true),set_config('gatherly.other',gen_random_uuid()::text,true),set_config('gatherly.listing',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at) select current_setting('gatherly.'||x)::uuid,gen_random_uuid()::text||'@example.invalid',now() from unnest(array['creator','buyer','other']) x;
insert into public.social_profiles(id,display_name) select current_setting('gatherly.'||x)::uuid,'Commerce Test '||x from unnest(array['creator','buyer','other']) x;
insert into gatherly_ops.payout_identity values(current_setting('gatherly.creator')::uuid,'Test','Creator',now());
insert into gatherly_ops.wallets(creator_id,address,network,asset,provider,provider_confirmed_at) values(current_setting('gatherly.creator')::uuid,'test-only-address','BITCOIN','BTC','luno',now());
insert into public.gatherly_posts(id,author_id,title,body,kind,price_minor) values(current_setting('gatherly.listing')::uuid,current_setting('gatherly.creator')::uuid,'Test photo','Rollback only','photo',10000);
select set_config('request.jwt.claim.role','authenticated',true);
set local role authenticated;
do $$begin
 begin perform public.gatherly_commerce('{"action":"settle"}');raise exception 'FAIL client could settle';exception when insufficient_privilege then null;end;
end$$;
reset role;
select set_config('request.jwt.claim.role','service_role',true);
do $$declare c uuid:=current_setting('gatherly.creator')::uuid;b uuid:=current_setting('gatherly.buyer')::uuid;l uuid:=current_setting('gatherly.listing')::uuid; other_id uuid:=current_setting('gatherly.other')::uuid;r jsonb;o uuid;key uuid:=gen_random_uuid(); payment jsonb;
begin
 r:=public.gatherly_commerce(jsonb_build_object('action','reserve_media','actor',c,'listing_id',l,'mime','image/png','size_bytes',123));
 if r->>'path' is null then raise exception 'FAIL missing upload path';end if;
 perform public.gatherly_commerce(jsonb_build_object('action','verify_media','actor',c,'listing_id',l));
 perform public.gatherly_commerce(jsonb_build_object('action','access','actor',c,'listing_id',l));
 begin perform public.gatherly_commerce(jsonb_build_object('action','access','actor',b,'listing_id',l));raise exception 'FAIL access without purchase';exception when insufficient_privilege then null;end;
 begin perform public.gatherly_commerce(jsonb_build_object('action','publish','actor',b,'listing_id',l,'confirm_review','YES'));raise exception 'FAIL member published';exception when raise_exception then if sqlerrm='FAIL member published' then raise;end if;end;
 update public.gatherly_posts set status='published' where id=l;
 update gatherly_ops.media set reviewed_by=c where listing_id=l;
 r:=public.gatherly_commerce(jsonb_build_object('action','reserve_order','actor',b,'listing_id',l,'idempotency_key',key));o:=(r->'order'->>'id')::uuid;
 if not (r->>'created')::boolean then raise exception 'FAIL no order';end if;
 r:=public.gatherly_commerce(jsonb_build_object('action','reserve_order','actor',b,'listing_id',l,'idempotency_key',key));
 if (r->>'created')::boolean or (r->'order'->>'id')::uuid<>o then raise exception 'FAIL duplicate order';end if;
 perform public.gatherly_commerce(jsonb_build_object('action','attach_invoice','order_id',o,'invoice_id',o::text,'invoice_url','https://nowpayments.io/payment/test'));
 payment:=jsonb_build_object('action','settle','order_id',o,'invoice_id',o::text,'payment_id',o::text,'gross_minor',10000,'currency','ZAR');
 begin perform public.gatherly_commerce(payment||'{"gross_minor":100}'::jsonb);raise exception 'FAIL wrong amount accepted';exception when raise_exception then if sqlerrm='FAIL wrong amount accepted' then raise;end if;end;
 perform public.gatherly_commerce(payment);perform public.gatherly_commerce(payment);
 if (select count(*) from gatherly_ops.ledger where order_id=o)<>1 or (select sum(amount_minor) from gatherly_ops.ledger where order_id=o)<>8500 then raise exception 'FAIL duplicate credit or wrong commission';end if;
 perform public.gatherly_commerce(jsonb_build_object('action','access','actor',b,'listing_id',l));
 begin perform public.gatherly_commerce(jsonb_build_object('action','access','actor',other_id,'listing_id',l));raise exception 'FAIL unrelated buyer access';exception when insufficient_privilege then null;end;
 perform public.gatherly_commerce(payment||'{"action":"refund"}'::jsonb);perform public.gatherly_commerce(payment||'{"action":"refund"}'::jsonb);perform public.gatherly_commerce(payment);
 if (select sum(amount_minor) from gatherly_ops.ledger where order_id=o)<>0 then raise exception 'FAIL refund not reversed';end if;
 begin perform public.gatherly_commerce(jsonb_build_object('action','access','actor',b,'listing_id',l));raise exception 'FAIL refund still grants access';exception when insufficient_privilege then null;end;
end$$;
rollback;
